(255307, 'tilnage', 0, '-1', ' tiltage, tilbage, til nage', 'lognok', '', '', 'Ordet findes ikke i RO eller ddoo. Mon der menes \"tilbage\"?, bogstaverne \'b\' og \'n\' sidder ved siden af hinanden på qwerty-keyboardet.', '0', '', '', '', '', '***** 19-04-2008 19:10 *****\nBehandler: lognok\nOrd: tilnage\nStatus: -1\nKommentar: Ordet findes ikke i RO eller ddoo. Mon der menes \"tilbage\"?, bogstaverne \'b\' og \'n\' sidder ved siden af hinanden på qwerty-keyboardet.\n\n', NULL, NULL),
(255308, 'meger', 0, '-1', ' neger, mager, mejer, eger, reger, leger, peger, beger, muger, møger, måger, mener, meter, meler, meder', 'lognok', '', '', 'Ordet findes ikke i RO eller ddoo. Mon der menes \"mere\"?, hvis man udtaler \"meger\", så lyder det meget som ordet \"mere\". Ellers kan der også være ordet \"neger\", da bogstaverne \'m\' og \'n\' ligger ved siden af hinanden på qwerty-keyboardet.', '0', '', '', '', '', '***** 19-04-2008 19:13 *****\nBehandler: lognok\nOrd: meger\nStatus: -1\nKommentar: Ordet findes ikke i RO eller ddoo. Mon der menes \"mere\"?, hvis man udtaler \"meger\", så lyder det meget som ordet \"mere\". Ellers kan der også være ordet \"neger\", da bogstaverne \'m\' og \'n\' ligger ved siden af hinanden på qwerty-keyboardet.\n\n', NULL, NULL),
(255309, 'Resum', 0, '-1', ' Resume, Re sum, Res um', 'esben', '', '', 'Ordet findes ikke i RO eller ddoo, men det figurerer på denne side fra finansministeriet: http://www.personalestyrelsen.dk/visSideforloeb.asp?artikelID=10914\r\n\r\nKommer det fra ordet \"resumé\"?.\r\n\r\nDet er ikke et fornavn eller et frit efternavn, og da det kun er egennavne der starter med stort begyndelsesbogstave slettes dette!', '0', '', '', '', '', '***** 19-02-2011 12:07 *****\nBehandler: esben\nOrd: Resum\nStatus: -1\nKommentar: Ordet findes ikke i RO eller ddoo, men det figurerer på denne side fra finansministeriet: http://www.personalestyrelsen.dk/visSideforloeb.asp?artikelID=10914\r\n\r\nKommer det fra ordet \"resumé\"?.\r\n\r\nDet er ikke et fornavn eller et frit efternavn, og da det kun er egennavne der starter med stort begyndelsesbogstave slettes dette!\n\n', NULL, NULL),
